    form=`<input type="hidden" name="recordId" value="${e(record?.id||'')}"/><input type="hidden" name="projectId" value="${e(projectId)}"/><div class="form-grid">${selectField('Part','partId',active(data.parts).map(p=>[p.id,`${p.code} · ${p.name}`]),record?.partId||active(data.parts)[0]?.id).replace('<select ','<select '+(record?'disabled ':''))}${record?`<input type="hidden" name="partId" value="${record.partId}"/>`:''}${field('Required quantity','required','number',record?.required??1,true,'min="1" step="1"')}</div>`;
    hint='A BOM requirement does not automatically reserve or receive stock.';
