    const record=m.id?data.updates.find(x=>x.id===m.id):null;title=record?'Edit customer progress draft':'Prepare customer progress update';submit=record?'Save changes':'Save draft';
    form=`<input type="hidden" name="recordId" value="${e(record?.id||'')}"/><input type="hidden" name="projectId" value="${e(record?.projectId||m.project||ui.project)}"/><div class="form-grid">${field('Public update title','title','text',record?.title||'')}${selectField('Update category','kind',['Milestone','Component','Manufacturing','Quality','Delivery'].map(x=>[x,x]),record?.kind||'Milestone')}${field('Related component','part','text',record?.part||'',false)}${textareaField('Customer-facing summary','description',record?.description||'')}</div>`;
