function openModal(type,details={}){ui.modal={type,...details};render()}
function closeModal(){ui.modal=null;render()}
function changePage(page){ui.page=page;ui.modal=null;render()}
function exportWbs(projectId){
  const project=findProject(projectId);if(!project)throw Error('Project not found');
  const headings=['WBS','Section','Job','Department','Assigned to','Priority','Status','Due date','Predecessor'];
  const rows=[headings];active(data.sections).filter(s=>s.projectId===project.id).forEach((sec,i)=>{
    rows.push([`${i+1}.0`,sec.name,'','','','','','','']);
    const visited=new Set();let index=0;
    const visit=(task,wbs,depth)=>{if(visited.has(task.id)||depth>12)return;visited.add(task.id);
      rows.push([wbs,sec.name,task.title,task.department,task.assignee,task.priority,task.status,task.due,data.tasks.find(t=>t.id===task.blockedBy)?.title||'']);
      active(data.tasks).filter(t=>t.parentId===task.id).forEach((child,k)=>visit(child,`${wbs}.${k+1}`,depth+1));
    };
    active(data.tasks).filter(t=>t.sectionId===sec.id&&!t.parentId).forEach(t=>visit(t,`${i+1}.${++index}`,0));
  });
  const csv=rows.map(row=>row.map(value=>'"'+String(value??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');
  const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}));
  const a=document.createElement('a');a.href=url;a.download=`${project.code}-WBS.csv`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);
}
function handleAction(el){const action=el.dataset.action,id=el.dataset.id;
 try{switch(action){
  case 'nav':changePage(id);break;
  case 'project-open':ui.page='projects';ui.project=id;ui.projectTab='structure';render();document.getElementById('project-detail')?.scrollIntoView({behavior:'smooth',block:'start'});break;
  case 'project-tab':ui.projectTab=id;render();break;
  case 'client-tab':ui.clientTab=id;render();break;
  case 'task-board':ui.taskView='board';render();break;
  case 'task-list':ui.taskView='list';render();break;
  case 'department-open':ui.dept=id;ui.page='tasks';render();break;
  case 'open-project-modal':openModal('project');break;
  case 'edit-project':openModal('project',{id});break;
  case 'edit-customer':openModal('customer',{id});break;
  case 'edit-task':openModal('task',{id});break;
  case 'add-subtask':{const t=data.tasks.find(x=>x.id===id);if(t)openModal('task',{project:t.projectId,parent:t.id,section:t.sectionId});break;}
  case 'add-section':openModal('section',{project:el.dataset.project||ui.project});break;
  case 'edit-section':openModal('section',{id});break;
  case 'add-part':openModal('part');break;
  case 'edit-part':openModal('part',{id});break;
  case 'add-bom':openModal('bom',{project:el.dataset.project||ui.project});break;
  case 'edit-bom':openModal('bom',{id});break;
  case 'edit-document':openModal('document',{id});break;
  case 'edit-update':openModal('update',{id});break;
  case 'open-task-modal':openModal('task',{project:el.dataset.project||ui.project});break;
  case 'open-customer-modal':openModal('customer');break;
  case 'open-po-modal':openModal('po');break;
  case 'stock-modal':openModal('stock',{id});break;
  case 'invite-modal':openModal('invite',{org:el.dataset.org||ui.clientOrg});break;
  case 'open-update-modal':openModal('update',{project:el.dataset.project||ui.project});break;
  case 'open-document-modal':openModal('document',{project:el.dataset.project||ui.project});break;
  case 'open-client-document-modal':openModal('client-document');break;
  case 'customer-detail':ui.customerDetail=id;render();break;
  case 'close-modal':case 'dismiss-modal':closeModal();break;
  case 'theme':data.settings.theme=data.settings.theme==='light'?'dark':'light';persist();render();break;
  case 'toggle-task':{const t=data.tasks.find(x=>x.id===id);if(t){setTaskStatus(data,id,t.status==='Done'?'Ready':'Done');persist();render();toast('Job status saved locally')}break;}
  case 'publish':{if(confirm('Publish this exact draft to the customer preview?')){publishUpdate(data,id);persist();render();toast('Update published to the demo customer portal')}break;}
  case 'withdraw-update':{const u=data.updates.find(x=>x.id===id);if(u?.status==='published'&&confirm('Withdraw this customer update? It will no longer be visible in the demo portal.')){u.status='withdrawn';audit('Customer publication withdrawn',u.title);persist();render();toast('Publication withdrawn')}break;}
  case 'archive-record':{const kind=el.dataset.kind,row=data[kind]?.find(x=>x.id===id);if(row&&confirm(`Archive ${row.name||row.title||row.code||id}?\nThe record stays in history and may be restored in Settings.`)){archiveRecord(data,kind,id);persist();render();toast('Record archived · restore from Settings')}break;}
  case 'restore-record':{restoreRecord(data,el.dataset.kind,id);persist();render();toast('Record restored');break;}
  case 'export-wbs':{exportWbs(id);toast('Project work breakdown exported as CSV');break;}
  case 'decide-approval':{decideApproval(data,id,el.dataset.decision);notify(`Client decision: ${el.dataset.decision}`);persist();render();toast(`Decision recorded: ${el.dataset.decision}`);break;}
  case 'receive-po':{receiveOrder(data,id);persist();render();toast('Outstanding purchase order quantities received into stock');break;}
  case 'notifications':openModal('notifications');break;
  case 'mark-read':data.notifications.forEach(x=>x.read=true);persist();closeModal();toast('Notifications marked as read');break;
  case 'reset-demo':if(confirm('Reset all local demo records and changes? This cannot be undone.')){data=seed();persist();ui.page='overview';ui.project='p1';ui.clientOrg='noah';ui.clientProject='p1';render();toast('Demo reset to original sample data')}break;
  case 'refresh':render();toast('Dashboard refreshed from local demo records');break;
  }}catch(err){toast(err.message||'Unable to complete this action',true)}
}
function formHandler(form){const fd=new FormData(form);const get=n=>String(fd.get(n)||'').trim();const type=form.dataset.form;
 try{switch(type){
  case 'project':{
    const existing=get('recordId');const record=saveProject(data,{id:existing||null,orgId:get('orgId'),name:get('name'),template:get('template'),status:get('status'),phase:get('phase'),due:get('due'),budget:get('budget'),contract:get('contract'),lead:get('lead'),description:get('description')});
    if(!existing){const names=record.template==='DA62'?['Cockpit','Visual system','Avionics','Testing & delivery']:record.template==='Motion Upgrade'?['Mechanics','Control systems','Installation & test']:['Cockpit & structure','Control loading','Visual system','Avionics & software','Testing & delivery'];names.forEach(name=>saveSection(data,{projectId:record.id,name,weight:Math.round(100/names.length)}));}
    ui.project=record.id;ui.page='projects';ui.projectTab='structure';break;
  }
  case 'customer':{
    const org=saveOrganization(data,{id:get('recordId')||null,name:get('name'),code:get('code'),contact:get('contact'),accent:get('accent')});ui.customerDetail=org.id;ui.page='customers';break;
  }
  case 'task':{
    const record=saveTask(data,{id:get('recordId')||null,projectId:get('projectId'),sectionId:get('sectionId'),title:get('title'),department:get('department'),assignee:get('assignee'),priority:get('priority'),status:get('status'),due:get('due'),parentId:get('parentId'),blockedBy:get('blockedBy')});ui.project=record.projectId;ui.page='projects';ui.projectTab='structure';break;
  }
  case 'section':{
    const record=saveSection(data,{id:get('recordId')||null,projectId:get('projectId'),name:get('name'),weight:get('weight')});ui.project=record.projectId;ui.page='projects';ui.projectTab='structure';break;
  }
  case 'part':{
    savePart(data,{id:get('recordId')||null,code:get('code'),name:get('name'),unit:get('unit'),supplier:get('supplier'),location:get('location'),min:get('min'),cost:get('cost')});ui.page='inventory';break;
  }
  case 'bom':{
    const record=saveBomLine(data,{id:get('recordId')||null,projectId:get('projectId'),partId:get('partId'),required:get('required')});ui.project=record.projectId;ui.page='projects';ui.projectTab='bom';break;
  }
  case 'stock':{stockMove(data,{partId:get('partId'),quantity:get('quantity'),type:get('type')});ui.page='inventory';break;}
  case 'po':{const part=findPart(get('partId'));if(!part)throw Error('Part not found');const q=Number(get('quantity')),cost=Number(get('unitCost'));if(!Number.isInteger(q)||q<1||!Number.isFinite(cost)||cost<0)throw Error('Check order quantity and unit cost');const code=`PO-${new Date().getFullYear().toString().slice(2)}${String(data.orders.length+120).padStart(4,'0')}`;data.orders.unshift({id:uid('po'),code,projectId:get('projectId'),supplier:get('supplier')||part.supplier,date:today(),status:'Awaiting delivery',items:[{partId:part.id,quantity:q,received:0,unitCost:cost}]});audit('Purchase order created',code);ui.page='purchasing';break;}
  case 'invite':{clientInvite(data,{orgId:get('orgId'),name:get('name'),email:get('email'),role:get('role'),projectIds:[get('projectId')]});ui.page=ui.page==='client'?'client':'customers';break;}
  case 'update':{const id=get('recordId');const record=id?data.updates.find(x=>x.id===id):null;if(record){if(record.status!=='draft')throw Error('Only drafts can be edited');Object.assign(record,{title:get('title'),kind:get('kind'),part:get('part'),description:get('description')});audit('Customer draft updated',record.title)}else{data.updates.unshift({id:uid('u'),projectId:get('projectId'),title:get('title'),kind:get('kind'),part:get('part'),description:get('description'),date:today(),status:'draft'});audit('Customer update drafted',get('title'))}ui.page='projects';ui.project=get('projectId');ui.projectTab='publishing';break;}
  case 'document':case 'client-document':{const record=get('recordId')?data.documents.find(x=>x.id===get('recordId')):null;const visibility=type==='client-document'?'internal':get('visibility');if(record){if(record.rev!==get('rev')&&record.visibility==='customer')record.visibility='internal';Object.assign(record,{title:get('title'),rev:get('rev'),type:get('type'),visibility:record.rev!==get('rev')?'internal':visibility,date:today()});audit('Document metadata updated',record.title)}else{data.documents.unshift({id:uid('d'),projectId:get('projectId'),title:get('title'),rev:get('rev'),type:get('type'),visibility,date:today()});audit(type==='client-document'?'Customer document metadata submitted':'Document registered',get('title'))}break;}
  case 'message':{const text=get('text');if(!text)throw Error('Enter a message');data.messages.push({id:uid('msg'),projectId:ui.clientProject,author:'Customer demo user',text,visibility:'customer',at:new Date().toISOString()});audit('Customer message drafted',`Message in ${ui.clientProject}`);break;}
  default:return;
 }ui.modal=null;persist();render();toast(type==='invite'?'Demo invitation recorded — no email sent':type==='client-document'?'Metadata saved for internal review — no file uploaded':'Saved to local demo workspace');
 }catch(err){toast(err.message||'Unable to save form',true)}
}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(el){if(el.dataset.action==='dismiss-modal'&&ev.target!==el)return;handleAction(el)}});
document.addEventListener('submit',ev=>{const form=ev.target.closest('form[data-form]');if(form){ev.preventDefault();formHandler(form)}});
document.addEventListener('change',ev=>{try{const el=ev.target;const filter=el.dataset.filter;
 if(filter==='dept'){ui.dept=el.value;render()}
 else if(filter==='taskProject'){ui.taskProject=el.value;render()}
 else if(filter==='clientOrg'){ui.clientOrg=el.value;ui.clientProject=activeOrgProjects(el.value)[0]?.id;ui.clientTab='updates';render()}
 else if(filter==='clientProject'){ui.clientProject=el.value;render()}
 else if(filter==='modalProject'){ui.modal.project=el.value;render()}
 else if(el.dataset.taskStatus){setTaskStatus(data,el.dataset.taskStatus,el.value);persist();render();toast('Job status updated')}
}catch(err){toast(err.message||'Cannot update status',true);render()}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&ui.modal)closeModal()});
render();